### Objective
Build a production-grade Interactive Micro-Interaction Suite in Flutter demonstrating declarative implicit animations: an expandable animated status card using `AnimatedContainer`, an animated toggle switch with `AnimatedAlign`, a notification cross-fader using `AnimatedCrossFade`, and a high-performance numeric metric counter using `TweenAnimationBuilder` with child render caching.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const ImplicitAnimationSuiteApp());
}

class ImplicitAnimationSuiteApp extends StatelessWidget {
  const ImplicitAnimationSuiteApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Implicit Animations Masterclass',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.indigo,
        useMaterial3: true,
      ),
      home: const MotionShowcaseScreen(),
    );
  }
}

class MotionShowcaseScreen extends StatefulWidget {
  const MotionShowcaseScreen({super.key});

  @override
  State<MotionShowcaseScreen> createState() => _MotionShowcaseScreenState();
}

class _MotionShowcaseScreenState extends State<MotionShowcaseScreen> {
  bool _isCardExpanded = false;
  bool _isToggleActive = false;
  bool _showDetails = false;
  double _targetMetric = 1250.0;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Implicit Animation Architecture'),
        centerTitle: true,
      ),
      body: ListView( 
        padding: const EdgeInsets.all(20.0),
        children: [
          _buildSectionHeader('1. AnimatedContainer: Expandable Card'),
          const SizedBox(height: 10),
          _buildExpandableCard(),
          const SizedBox(height: 24),
          _buildSectionHeader('2. AnimatedAlign: Custom Toggle Switch'),
          const SizedBox(height: 10),
          _buildCustomToggle(),
          const SizedBox(height: 24),
          _buildSectionHeader('3. AnimatedCrossFade: View Switcher'),
          const SizedBox(height: 10),
          _buildCrossFadeSection(),
          const SizedBox(height: 24),
          _buildSectionHeader('4. TweenAnimationBuilder: High-Speed Counter'),
          const SizedBox(height: 10),
          _buildCounterSection(),
        ],
      ),
    );
  }

  Widget _buildSectionHeader(String title) {
    return Text(
      title,
      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
    );
  }

  Widget _buildExpandableCard() {
    final colorScheme = Theme.of(context).colorScheme;

    return GestureDetector(
      onTap: () {
        setState(() {
          _isCardExpanded = !_isCardExpanded;
        });
      },
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 400),
        curve: Curves.fastOutSlowIn,
        padding: const EdgeInsets.all(18.0),
        decoration: BoxDecoration(
          color: _isCardExpanded
              ? colorScheme.primaryContainer
              : colorScheme.surfaceContainerHighest,
          borderRadius: BorderRadius.circular(_isCardExpanded ? 24.0 : 12.0),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: _isCardExpanded ? 0.15 : 0.04),
              blurRadius: _isCardExpanded ? 16.0 : 4.0,
              offset: Offset(0, _isCardExpanded ? 8 : 2),
            ),
          ],
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Row(
                  children: [
                    Icon(
                      Icons.insights_rounded,
                      color: _isCardExpanded
                          ? colorScheme.primary
                          : colorScheme.onSurfaceVariant,
                    ),
                    const SizedBox(width: 10),
                    Text(
                      'Cloud Infrastructure Health',
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        color: _isCardExpanded
                            ? colorScheme.primary
                            : colorScheme.onSurfaceVariant,
                      ),
                    ),
                  ],
                ),
                AnimatedRotation(
                  turns: _isCardExpanded ? 0.5 : 0.0,
                  duration: const Duration(milliseconds: 400),
                  curve: Curves.fastOutSlowIn,
                  child: const Icon(Icons.keyboard_arrow_down_rounded),
                ),
              ],
            ),
            AnimatedCrossFade(
              duration: const Duration(milliseconds: 300),
              crossFadeState: _isCardExpanded
                  ? CrossFadeState.showSecond
                  : CrossFadeState.showFirst,
              firstChild: const Padding(
                padding: EdgeInsets.only(top: 8.0),
                child: Text(
                  'Tap to inspect live server nodes and CPU load.',
                  style: TextStyle(fontSize: 12, color: Colors.black54),
                ),
              ),
              secondChild: const Padding(
                padding: EdgeInsets.only(top: 14.0),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Divider(),
                    SizedBox(height: 6),
                    Text('• 12 / 12 Kubernetes Pods Healthy', style: TextStyle(fontSize: 13)),
                    SizedBox(height: 4),
                    Text('• Average Response Latency: 24ms', style: TextStyle(fontSize: 13)),
                    SizedBox(height: 4),
                    Text('• Regional Failover: ACTIVE (us-east-1)', style: TextStyle(fontSize: 13)),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildCustomToggle() {
    final colorScheme = Theme.of(context).colorScheme;

    return Row(
      children: [
        GestureDetector(
          onTap: () {
            setState(() {
              _isToggleActive = !_isToggleActive;
            });
          },
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 250),
            curve: Curves.easeInOut,
            width: 72,
            height: 38,
            padding: const EdgeInsets.symmetric(horizontal: 4.0),
            decoration: BoxDecoration(
              color: _isToggleActive
                  ? colorScheme.primary
                  : colorScheme.surfaceContainerHighest,
              borderRadius: BorderRadius.circular(999),
            ),
            child: AnimatedAlign(
              duration: const Duration(milliseconds: 250),
              curve: Curves.easeOutCubic,
              alignment: _isToggleActive
                  ? Alignment.centerRight
                  : Alignment.centerLeft,
              child: Container(
                width: 30,
                height: 30,
                decoration: const BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black26,
                      blurRadius: 4,
                      offset: Offset(0, 2),
                    ),
                  ],
                ),
                child: Icon(
                  _isToggleActive ? Icons.check : Icons.close,
                  size: 18,
                  color: _isToggleActive ? colorScheme.primary : Colors.grey,
                ),
              ),
            ),
          ),
        ),
        const SizedBox(width: 16),
        Text(
          _isToggleActive ? 'Production Mode: ON' : 'Production Mode: OFF',
          style: const TextStyle(fontWeight: FontWeight.w600),
        ),
      ],
    );
  }

  Widget _buildCrossFadeSection() {
    return Card(
      elevation: 0,
      color: Theme.of(context).colorScheme.surfaceContainerLow,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            AnimatedCrossFade(
              duration: const Duration(milliseconds: 350),
              crossFadeState: _showDetails
                  ? CrossFadeState.showSecond
                  : CrossFadeState.showFirst,
              firstChild: const ListTile(
                leading: Icon(Icons.security_rounded, color: Colors.blue, size: 32),
                title: Text('Standard Authentication'),
                subtitle: Text('Password and SMS 2FA enabled.'),
              ),
              secondChild: const ListTile(
                leading: Icon(Icons.fingerprint_rounded, color: Colors.green, size: 32),
                title: Text('Biometric Security Matrix'),
                subtitle: Text('Hardware Secure Enclave & FIDO2 Passkeys Active.'),
              ),
            ),
            const SizedBox(height: 8),
            OutlinedButton.icon(
              onPressed: () {
                setState(() {
                  _showDetails = !_showDetails;
                });
              },
              icon: const Icon(Icons.swap_horiz_rounded),
              label: const Text('Toggle Security Configuration'),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildCounterSection() {
    final colorScheme = Theme.of(context).colorScheme;

    return Card(
      elevation: 1,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(20.0),
        child: Column(
          children: [
            const Text(
              'Real-Time Daily Active Transactions',
              style: TextStyle(color: Colors.black54, fontSize: 13),
            ),
            const SizedBox(height: 12),
            TweenAnimationBuilder<double>(
              tween: Tween<double>(begin: 0.0, end: _targetMetric),
              duration: const Duration(milliseconds: 1200),
              curve: Curves.easeOutExpo,
              builder: (context, value, child) {
                return Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.baseline,
                  textBaseline: TextBaseline.alphabetic,
                  children: [
                    Text(
                      '\$${value.toStringAsFixed(0)}',
                      style: TextStyle(
                        fontSize: 36,
                        fontWeight: FontWeight.w900,
                        color: colorScheme.primary,
                        fontFeatures: const [FontFeature.tabularFigures()],
                      ),
                    ),
                    if (child != null) child,
                  ],
                );
              },
              child: const Padding(
                padding: EdgeInsets.only(left: 6.0),
                child: Text(
                  'USD',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.bold,
                    color: Colors.black45,
                  ),
                ),
              ),
            ),
            const SizedBox(height: 16),
            Wrap(
              spacing: 8,
              children: [
                ElevatedButton(
                  onPressed: () => setState(() => _targetMetric = 500.0),
                  child: const Text('Reset: $500'),
                ),
                ElevatedButton(
                  onPressed: () => setState(() => _targetMetric = 2450.0),
                  child: const Text('Surge: $2,450'),
                ),
                ElevatedButton(
                  onPressed: () => setState(() => _targetMetric = 9980.0),
                  child: const Text('Peak: $9,980'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Expandable Card with `AnimatedContainer`**:
   `_buildExpandableCard` modulates container padding, decoration color, and corner radius based on `_isCardExpanded`. Notice the nested `AnimatedRotation`: by passing `turns: _isCardExpanded ? 0.5 : 0.0`, the chevron rotates 180 degrees smoothly on the exact same duration curve.
2. **Custom Micro-Interaction with `AnimatedAlign`**:
   Instead of third-party packages, `_buildCustomToggle` builds a 60 FPS toggle switch in 20 lines of code. `AnimatedContainer` shifts track background colors while `AnimatedAlign` animates the thumb horizontal alignment from `Alignment.centerLeft` to `Alignment.centerRight`.
3. **View Switching with `AnimatedCrossFade`**:
   `_buildCrossFadeSection` transitions between standard and biometric security states without layout popping. `AnimatedCrossFade` automatically measures both children and animates the container height to accommodate differences in content size.
4. **Interpolated Counter with `TweenAnimationBuilder`**:
   `_buildCounterSection` animates financial metrics using `Curves.easeOutExpo`. Passing the static `'USD'` label into the `child` parameter ensures it is instantiated once and passed directly into the builder, guaranteeing zero garbage collection pressure during frame rendering.
